const res = $input.first().json;
const html = res.data ?? (typeof res === 'string' ? res : JSON.stringify(res));
const normalized = String(html)
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// djb2-xor hash: no imports, works in the sandboxed Code node.
let hash = 5381;
for (let i = 0; i < normalized.length; i++) {
  hash = ((hash * 33) ^ normalized.charCodeAt(i)) >>> 0;
}
const current = String(hash);

const store = $getWorkflowStaticData('global');
const previous = store.lastHash;
store.lastHash = current;

return [
  {
    json: {
      url: $('Settings').first().json.url,
      changed: previous !== current,
      firstRun: previous === undefined,
      previousHash: previous ?? null,
      currentHash: current,
    },
  },
];

